`]}),`
`,a.jsxs(e.li,{children:[`
`,a.jsx(e.p,{children:"Designing authoritative server architecture to prevent desync"}),`
`]}),`
`,a.jsxs(e.li,{children:[`
`,a.jsx(e.p,{children:"Using nanoId for scalable, collision-resistant identifiers"}),`
`]}),`
`,a.jsxs(e.li,{children:[`
`,a.jsx(e.p,{children:"Managing deployment and infrastructure on AWS"}),`
`]}),`
`,a.jsxs(e.li,{children:[`
`,a.jsx(e.p,{children:"Handling drag-and-drop mechanics cleanly in React"}),`
`]}),`
`,a.jsxs(e.li,{children:[`
`,a.jsx(e.p,{children:"Balancing performance with development velocity"}),`
`]}),`
`]}),`
`,a.jsx(e.hr,{}),`
`,a.jsx(e.h2,{children:"What's Next"}),`
`,a.jsx(e.p,{children:"The next step is improving UI polish and responsiveness. The core game works, but the experience can feel sharper - better animations, clearer feedback, and improved mobile responsiveness would elevate the gameplay significantly."}),`
`,a.jsx(e.p,{children:"I also want to improve matchmaking reliability and scalability. Moving from in-memory queues to a more persistent or distributed approach would make the system more production-ready. Performance tuning beyond the current 20 FPS update cycle is another area I’d like to explore once the infrastructure becomes more robust."})]})}function NC(i={}){const{wrapper:e}=i.components||{};return e?a.jsx(e,{...i,children:a.jsx(Ey,{...i})}):Ey(i)}function My(i){const e={h2:"h2",hr:"hr",li:"li",p:"p",strong:"strong",ul:"ul",...i.components};return a.jsxs(a.Fragment,{children:[a.jsx(e.hr,{}),`
`,a.jsx(e.h2,{children:"Introduction"}),`
`,a.jsx(e.p,{children:"This project started as a simple experiment to learn web scraping. I just wanted to pull some movie data and understand how scraping pipelines worked end-to-end."}),`
`,a.jsx(e.p,{children:"But as I was building it, I realized the data itself was actually interesting. Instead of stopping at a CSV file, I decided to turn it into something visual — a dashboard that shows where the top 100 most popular movies on IMDb were filmed. I’ve always thought 3D globe visualizations on the web looked cool, so this felt like the perfect excuse to finally use one."}),`
`,a.jsx(e.p,{children:"The result is a full-stack application that scrapes IMDb every 6 hours via an automated ETL pipeline and visualizes filming locations on an interactive globe."}),`
`,a.jsx(e.hr,{}),`
