`,a.jsx(e.p,{children:"This project was built as a personal exploration into quantitative trading systems and high-performance software engineering. Having previously participated in a quant trading hackathon using Python, I wanted to better understand the engineering side of financial systems while deepening my knowledge of modern C++."}),`
`,a.jsx(e.p,{children:"The goal was not to build a profitable trading strategy, but rather to investigate how different order book implementations behave under varying market conditions. In financial markets, order books sit at the core of exchanges, and even small inefficiencies can significantly impact latency and throughput."}),`
`,a.jsx(e.p,{children:"To explore these trade-offs, I implemented multiple order book designs using different C++ data structures and benchmarked them against simulated market environments."}),`
`,a.jsx(e.hr,{}),`
`,a.jsx(e.h2,{children:"Project Overview"}),`
`,a.jsx(e.p,{children:"The project simulates several order book implementations and evaluates their performance across different market scenarios."}),`
`,a.jsx(e.p,{children:"The implementations include:"}),`
`,a.jsxs(e.ul,{children:[`
`,a.jsx(e.li,{children:"Map-based order book"}),`
`,a.jsx(e.li,{children:"Unordered map-based order book"}),`
`,a.jsx(e.li,{children:"Vector-based order book"}),`
`,a.jsx(e.li,{children:"Priority queue-based order book"}),`
`]}),`
`,a.jsx(e.p,{children:"A separate market generator creates realistic trading conditions, allowing each implementation to be tested under:"}),`
`,a.jsxs(e.ul,{children:[`
`,a.jsx(e.li,{children:"Normal market activity"}),`
`,a.jsx(e.li,{children:"Price spikes"}),`
`,a.jsx(e.li,{children:"Trending markets"}),`
`,a.jsx(e.li,{children:"High-frequency trading (HFT) conditions"}),`
`,a.jsx(e.li,{children:"Random market behavior"}),`
`]}),`
`,a.jsx(e.p,{children:"Each implementation is benchmarked and ranked based on execution speed, throughput, and overall efficiency."}),`
